/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "owl",
  beads: 7,
  paced: /^co-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--co-c0": "oklch(0.62 0.03 260)", "--co-c1": "oklch(0.7 0.03 80)", "--co-c2": "oklch(0.58 0.03 300)" },
    live: { "--co-c0": "oklch(0.8 0.16 70)", "--co-c1": "oklch(0.94 0.04 95)", "--co-c2": "oklch(0.65 0.16 300)" },
  },
  turnVar: "--co-turn",
  paperVar: "--co-paper",
  view: VIEW,
};

export type OwlMarkProps = MarkProps;

export function OwlMark(props: OwlMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `co${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "co-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
